"""Generated by LeanFM from protocol Lending; regenerate it with session_skeleton rather than editing.

Each role's states are classes; a method consumes its state and returns the next. The start
functions are member, desk, librarian. A transport is a function that takes a message
(the logged event plus a body) and delivers it; log, if given, receives every event for
session_conform.
"""

from __future__ import annotations

import itertools
import re
import time
from dataclasses import dataclass
from typing import List, Optional


class ProtocolError(Exception):
    """A step the protocol does not allow here."""


_MAX_SAFE = 2**53 - 1
_DECIMAL = re.compile(r"-?[0-9]{1,20}")
_last_ts = 0


_clock = time.time_ns


def set_clock(clock):
    """Replace the clock events are stamped from (a function giving nanoseconds), for replayable runs."""
    global _clock, _last_ts
    _clock, _last_ts = clock, 0


def _now_ns():
    """Nanoseconds since the epoch, strictly increasing in this process: each event's ts."""
    global _last_ts
    _last_ts = max(_clock(), _last_ts + 1)
    return _last_ts


def _to_wire(kind, ref, value, where):
    if kind in ("nat", "int"):
        if isinstance(value, bool) or not isinstance(value, int) or (kind == "nat" and value < 0):
            raise ProtocolError(f"{where} is a {'Nat' if kind == 'nat' else 'Int'}, not {value!r}")
        return str(value)  # integers travel as decimal strings: exact past 2**53
    if kind == "str" and not isinstance(value, str) or kind == "bool" and not isinstance(value, bool):
        raise ProtocolError(f"{where} is a {'String' if kind == 'str' else 'Bool'}, not {value!r}")
    return _encode(ref, value, where) if kind == "msg" else value


def _encode(name, body, where=None):
    """A message of type name as its wire form, after checking every field against its type."""
    where = where or name
    if body is None:
        body = {}
    if isinstance(body, dict):
        try:
            body = TYPES[name](**body)
        except TypeError as e:
            raise ProtocolError(f"{where} does not fit {name}: {e}") from None
    if not isinstance(body, TYPES[name]):
        raise ProtocolError(f"{where} is a {name}, not {type(body).__name__}")
    out = {}
    for field, kind, ref, wrap in SCHEMA[name]:
        value, here = getattr(body, field), f"{where}.{field}"
        if wrap == "opt":
            if value is not None:
                out[field] = _to_wire(kind, ref, value, here)
        elif wrap == "list":
            if not isinstance(value, list):
                raise ProtocolError(f"{here} is a list, not {value!r}")
            out[field] = [_to_wire(kind, ref, v, here) for v in value]
        else:
            out[field] = _to_wire(kind, ref, value, here)
    return out


def _from_wire(kind, ref, value, where):
    if kind in ("nat", "int"):
        if isinstance(value, str) and _DECIMAL.fullmatch(value):
            n = int(value)
        elif isinstance(value, int) and not isinstance(value, bool) and abs(value) <= _MAX_SAFE:
            n = value  # a JSON number is exact only within 2**53 - 1
        else:
            raise ProtocolError(f"{where} is a {'Nat' if kind == 'nat' else 'Int'} as a decimal string, not {value!r}")
        if kind == "nat" and n < 0:
            raise ProtocolError(f"{where} is a Nat, not {n}")
        return n
    if kind == "str" and not isinstance(value, str) or kind == "bool" and not isinstance(value, bool):
        raise ProtocolError(f"{where} is a {'String' if kind == 'str' else 'Bool'}, not {value!r}")
    return _decode(ref, value, where) if kind == "msg" else value


def _decode(name, data, where=None):
    """A received body as its message type, refusing what does not fit."""
    where = where or name
    if data is None:
        data = {}
    if not isinstance(data, dict):
        raise ProtocolError(f"{where} is a {name}, not {data!r}")
    known = {f[0] for f in SCHEMA[name]}
    for key in data:
        if key not in known:
            raise ProtocolError(f"{where} has no field {key}")
    args = {}
    for field, kind, ref, wrap in SCHEMA[name]:
        value, here = data.get(field), f"{where}.{field}"
        if value is None:
            if wrap == "opt":
                args[field] = None
                continue
            if wrap == "list":
                args[field] = []
                continue
            raise ProtocolError(f"{here} is missing")
        if wrap == "list":
            if not isinstance(value, list):
                raise ProtocolError(f"{here} is a list, not {value!r}")
            args[field] = [_from_wire(kind, ref, v, here) for v in value]
        else:
            args[field] = _from_wire(kind, ref, value, here)
    return TYPES[name](**args)


def _project(body, paths):
    """The fields at these dotted paths of a body, nested as in the body; nothing else."""
    out = {}
    for path in paths:
        keys = path.split(".")
        cur = body
        for key in keys:
            if isinstance(cur, dict) and key in cur:
                cur = cur[key]
            else:
                break
        else:
            node = out
            for key in keys[:-1]:
                node = node.setdefault(key, {})
            node[keys[-1]] = cur
    return out


class Endpoint:
    """One role in one session. It numbers events, binds the protocol's message ids to the events
    that were those messages, fills in causes, logs every event, and hands messages to transport."""

    def __init__(self, role, session, transport, log=None, new_id=None):
        self.role, self.session = role, str(session)
        self.transport, self.log = transport, log
        counter = itertools.count(1)
        self.new_id = new_id or (lambda: f"{self.session}.{self.role}.{next(counter)}")
        self.bind = {}

    def send(self, to, label, pid, cause_pid, body, cause=None):
        body = _encode(label, body)
        if cause is None and cause_pid is not None:
            cause = self.bind.get(cause_pid)
            if cause is None:
                raise ProtocolError(f"{label} is caused by {cause_pid}, which has not happened in session {self.session}")
        event = {"ts": str(_now_ns()), "id": self.new_id(), "session": self.session, "from": self.role, "to": to, "label": label}
        if cause is not None:
            event["cause"] = cause
        if pid is not None:
            self.bind[pid] = event["id"]
        if self.log is not None:
            logged = dict(event)
            reads = READS.get(pid) if pid is not None else None
            if reads:
                # exactly the fields where conditions read; nothing else of the body is logged
                logged["fields"] = _project(body, reads)
            self.log(logged)
        self.transport(dict(event, body=body))
        return event

    def act(self, label):
        event = {"ts": str(_now_ns()), "id": self.new_id(), "session": self.session, "at": self.role, "label": label, "act": True}
        if self.log is not None:
            self.log(dict(event))
        return event

    def accepts(self, msg, src, label):
        return msg.get("label") == label and msg.get("from") == src and msg.get("to") == self.role

    def received(self, msg, pid):
        if str(msg.get("session")) != self.session:
            raise ProtocolError(f"a message of session {msg.get('session')} reached session {self.session}")
        if pid is not None:
            self.bind[pid] = msg["id"]
        # role code sees the body as its message type, never as raw JSON
        return dict(msg, body=_decode(msg["label"], msg.get("body"), msg["label"]))

    def refuse(self, state, msg, allowed):
        raise ProtocolError(f"{self.role} in {state} cannot receive {msg.get('label')} from {msg.get('from')}; "
                            f"it accepts {allowed}")


class State:
    """A typestate state. Each is used once: a method consumes it and returns the next state."""

    def __init__(self, ep):
        self._ep, self._used = ep, False

    def _take(self):
        if self._used:
            raise ProtocolError(f"{type(self).__name__} was already used; continue from the state it returned")
        self._used = True
        return self._ep

    @property
    def endpoint(self):
        return self._ep


class End(State):
    """The role has finished this session."""


class Fork:
    """Concurrent branches: run each state in branches toward End, then join to continue: with the
    End of every branch for par, or of need of them for join (the others keep running beside what
    follows). A role in fewer branches than a join needs waits for all of its own; whether the
    others have ended it cannot see, so session_conform holds the run to the count."""

    def __init__(self, branches, then, need=None):
        self.branches, self._then, self._joined = branches, then, False
        self.need = len(branches) if need is None else need

    def join(self, *ends):
        if self._joined:
            raise ProtocolError("this fork was already joined")
        if len(ends) < self.need or len(ends) > len(self.branches) or not all(isinstance(e, End) for e in ends):
            raise ProtocolError(f"join takes the End of {self.need} of the {len(self.branches)} branches")
        if len({id(e) for e in ends}) != len(ends):
            raise ProtocolError("join was given the same End twice")
        self._joined = True
        return self._then()


class Server:
    """Any number of sessions of the same body, each with its own endpoint."""

    def __init__(self, ep, start, then):
        self._ep, self._start, self._then = ep, start, then

    def session(self, session, transport=None, log=None, new_id=None):
        ep = Endpoint(self._ep.role, session, transport or self._ep.transport, log or self._ep.log, new_id)
        return self._start(ep)

    def then(self):
        return self._then(self._ep)
# The message types (selfhost.session.types): send methods take these; received bodies are these.

@dataclass
class Borrow:
    """The book a member asks to borrow."""
    book: str

@dataclass
class Hold:
    """The Desk asks the Librarian to approve a hold on the book."""
    book: str

@dataclass
class Return:
    book: str

@dataclass
class Lent:
    pass

@dataclass
class Returned:
    pass

@dataclass
class Approved:
    pass

@dataclass
class Waitlisted:
    pass

@dataclass
class Denied:
    pass

@dataclass
class Refused:
    pass


# Each type's fields as (name, kind, structure, list or option), for encoding and decoding.
SCHEMA = {
    "Borrow": [("book", "str", "", "")],
    "Hold": [("book", "str", "", "")],
    "Return": [("book", "str", "", "")],
    "Lent": [],
    "Returned": [],
    "Approved": [],
    "Waitlisted": [],
    "Denied": [],
    "Refused": []
}
TYPES = {"Borrow": Borrow, "Hold": Hold, "Return": Return, "Lent": Lent, "Returned": Returned, "Approved": Approved, "Waitlisted": Waitlisted, "Denied": Denied, "Refused": Refused}


# The fields of each message that where conditions and session keys read: logged, nothing else of a body.
READS = {}




class MemberS1(State):
    """Member at S1: send_borrow -> MemberS2."""

    def send_borrow(self, body: Borrow):
        ep = self._take()
        ep.send("Desk", "Borrow", "b", None, body)
        return MemberS2(ep)


class MemberS2(State):
    """Member at S2: receive(msg): Lent from Desk, Waitlisted from Desk, Refused from Desk."""

    def receive(self, msg):
        ep = self._ep
        if ep.accepts(msg, "Desk", "Lent"):
            self._take()
            msg = ep.received(msg, "l")
            return msg, MemberS3(ep)
        if ep.accepts(msg, "Desk", "Waitlisted"):
            self._take()
            msg = ep.received(msg, None)
            return msg, End(ep)
        if ep.accepts(msg, "Desk", "Refused"):
            self._take()
            msg = ep.received(msg, None)
            return msg, End(ep)
        ep.refuse("MemberS2", msg, "Lent from Desk, Waitlisted from Desk, Refused from Desk")


class MemberS3(State):
    """Member at S3: send_return -> MemberS4."""

    def send_return(self, body: Return):
        ep = self._take()
        ep.send("Desk", "Return", "r", None, body)
        return MemberS4(ep)


class MemberS4(State):
    """Member at S4: receive(msg): Returned from Desk."""

    def receive(self, msg):
        ep = self._ep
        if ep.accepts(msg, "Desk", "Returned"):
            self._take()
            msg = ep.received(msg, None)
            return msg, End(ep)
        ep.refuse("MemberS4", msg, "Returned from Desk")


def member(session, transport, log=None, new_id=None):
    """Member's start state in a new session."""
    return MemberS1(Endpoint("Member", session, transport, log, new_id))


class DeskS1(State):
    """Desk at S1: receive(msg): Borrow from Member."""

    def receive(self, msg):
        ep = self._ep
        if ep.accepts(msg, "Member", "Borrow"):
            self._take()
            msg = ep.received(msg, "b")
            return msg, DeskS2(ep)
        ep.refuse("DeskS1", msg, "Borrow from Member")


class DeskS2(State):
    """Desk at S2: send_lent -> DeskS3; send_hold -> DeskS5."""

    def send_lent(self, body: Optional[Lent] = None):
        ep = self._take()
        ep.send("Member", "Lent", "l", "b", body)
        return DeskS3(ep)

    def send_hold(self, body: Hold):
        ep = self._take()
        ep.send("Librarian", "Hold", "h", "b", body)
        return DeskS5(ep)


class DeskS3(State):
    """Desk at S3: receive(msg): Return from Member."""

    def receive(self, msg):
        ep = self._ep
        if ep.accepts(msg, "Member", "Return"):
            self._take()
            msg = ep.received(msg, "r")
            return msg, DeskS4(ep)
        ep.refuse("DeskS3", msg, "Return from Member")


class DeskS4(State):
    """Desk at S4: send_returned -> End."""

    def send_returned(self, body: Optional[Returned] = None):
        ep = self._take()
        ep.send("Member", "Returned", None, "r", body)
        return End(ep)


class DeskS5(State):
    """Desk at S5: receive(msg): Approved from Librarian, Denied from Librarian."""

    def receive(self, msg):
        ep = self._ep
        if ep.accepts(msg, "Librarian", "Approved"):
            self._take()
            msg = ep.received(msg, None)
            return msg, DeskS6(ep)
        if ep.accepts(msg, "Librarian", "Denied"):
            self._take()
            msg = ep.received(msg, None)
            return msg, DeskS7(ep)
        ep.refuse("DeskS5", msg, "Approved from Librarian, Denied from Librarian")


class DeskS6(State):
    """Desk at S6: send_waitlisted -> End."""

    def send_waitlisted(self, body: Optional[Waitlisted] = None):
        ep = self._take()
        ep.send("Member", "Waitlisted", None, "b", body)
        return End(ep)


class DeskS7(State):
    """Desk at S7: send_refused -> End."""

    def send_refused(self, body: Optional[Refused] = None):
        ep = self._take()
        ep.send("Member", "Refused", None, "b", body)
        return End(ep)


def desk(session, transport, log=None, new_id=None):
    """Desk's start state in a new session."""
    return DeskS1(Endpoint("Desk", session, transport, log, new_id))


class LibrarianS1(State):
    """Librarian at S1: receive(msg): Hold from Desk; skip -> End (the branch taken did not involve this role)."""

    def receive(self, msg):
        ep = self._ep
        if ep.accepts(msg, "Desk", "Hold"):
            self._take()
            msg = ep.received(msg, "h")
            return msg, LibrarianS2(ep)
        ep.refuse("LibrarianS1", msg, "Hold from Desk")

    def skip(self):
        return End(self._take())


class LibrarianS2(State):
    """Librarian at S2: send_approved -> End; send_denied -> End."""

    def send_approved(self, body: Optional[Approved] = None):
        ep = self._take()
        ep.send("Desk", "Approved", None, "h", body)
        return End(ep)

    def send_denied(self, body: Optional[Denied] = None):
        ep = self._take()
        ep.send("Desk", "Denied", None, "h", body)
        return End(ep)


def librarian(session, transport, log=None, new_id=None):
    """Librarian's start state in a new session."""
    return LibrarianS1(Endpoint("Librarian", session, transport, log, new_id))
